    Jurisdiction,
    TaxYear,
    InputSchema,
    OutputSchema
  >,
  input: InputSchema["Type"]
): Effect.Effect<
  OutputSchema["Type"],
  CalculatorServiceError | Schema.SchemaError,
  TaxKitEffectRequirements
> =>
  calculateReportRequest(calculation, {
    payload: {
      facts: input,
      jurisdiction: calculation.jurisdiction,
      taxYear: calculation.taxYear,
    },
  });

