  const normalizeJsonArray = (array: Schema.JsonArray): Schema.JsonArray =>
    EffectArray.map(array, normalizeJsonValue);
  const normalizeJsonObject = (object: Schema.JsonObject): Schema.JsonObject =>
    pipe(
