      ]),
      EffectRecord.fromEntries
    );

  return Schema.decodeUnknownOption(JsonArray)(value).pipe(
    Option.match({
      onNone: () =>
        Schema.decodeUnknownOption(JsonObject)(value).pipe(
          Option.match({
            onNone: () => value,
            onSome: normalizeJsonObject,
          })
        ),
      onSome: normalizeJsonArray,
    })
  );
